  "seen_amount",
  "seen_txid",
  "txid",
  "tx_received_amount",
  "confirmations",
  "paid_at",
  "expires_at",
  "late_payment_note",
  "asset",
  "required_confirmations",
  "provider",
  "provider_error",
  "last_checked_at"
